# Source from Zsh, or invoke with zsh. No external utilities are required.

_td_fail() { print -ru2 -- "tendora: $*"; return 1; }

_td_checksum() {
  local material=$1 ch
  local -i i code h=5381
  for (( i=1; i<=${#material}; i++ )); do
    ch=${material[i]}
    builtin printf -v code '%d' "'$ch"
    (( h = ((h * 33) ^ code) & 2147483647 ))
  done
  REPLY=$h
}

_td_transition() {
  local action=$1
  td_next_water=$td_water td_next_beds=$td_beds td_next_food=$td_food
  (( td_food < 12 )) || { _td_fail 'goal reached; this world is paused'; return 1; }
  case $action in
    collect) (( td_next_water += 3 ));;
    plant) (( td_next_water -= 2, td_next_beds += 1 ));;
    harvest) (( td_next_water -= 1, td_next_beds -= 1, td_next_food += 3 ));;
    *) _td_fail "unknown action: $action"; return 1;;
  esac
  (( td_next_water >= 2 && td_next_water <= 12 )) || {
    _td_fail "water must remain in [2,12]; $action would leave $td_next_water"; return 1
  }
  (( td_next_beds >= 0 && td_next_beds <= 3 )) || {
    _td_fail "beds must remain in [0,3]; $action would leave $td_next_beds"; return 1
  }
  (( td_next_food <= 12 )) || { _td_fail 'food goal would be exceeded'; return 1; }
  return 0
}

_td_load() {
  [[ -d $td_dir/events && -d $td_dir/proposals && ! -L $td_dir/events && ! -L $td_dir/proposals ]] || {
    _td_fail 'world missing or malformed; read README.md before init'; return 1
  }
  local file line body expected_name REPLY
  local -a fields files
  local -i expected=0
  td_water=4 td_beds=0 td_food=0 td_head=-1 td_digest=0 td_pending=0
  files=( "$td_dir"/events/*(DN) )
  for file in "${files[@]}"; do
    if [[ ${file:t} == .pending-* && -f $file && ! -L $file ]]; then
      (( td_pending += 1 )); continue
    fi
    builtin printf -v expected_name '%06d.receipt' $expected
    [[ ${file:t} == $expected_name && -f $file && ! -L $file ]] || {
      _td_fail "unexpected event or gap at $expected_name: ${file:t}"; return 1
    }
    line=$(<"$file")
    fields=( "${(@s:|:)line}" )
    (( ${#fields} == 8 )) && [[ $line != *$'\n'* ]] || {
      _td_fail "malformed receipt: ${file:t}"; return 1
    }
    [[ $fields[1] == TENDORA/1 && $fields[2] == $expected && $fields[3] == $td_digest ]] || {
      _td_fail "broken lineage: ${file:t}"; return 1
    }
    body="${(j:|:)fields[1,7]}"
    _td_checksum "$body"
    [[ $fields[8] == $REPLY ]] || { _td_fail "checksum mismatch: ${file:t}"; return 1; }
    if (( expected == 0 )); then
      [[ $fields[4] == awaken && $fields[5] == 4 && $fields[6] == 0 && $fields[7] == 0 ]] || {
        _td_fail 'invalid genesis'; return 1
      }
    else
      _td_transition "$fields[4]" || { _td_fail "invalid transition: ${file:t}"; return 1; }
      [[ $fields[5] == $td_next_water && $fields[6] == $td_next_beds && $fields[7] == $td_next_food ]] || {
        _td_fail "state disagrees with replay: ${file:t}"; return 1
      }
      td_water=$td_next_water td_beds=$td_next_beds td_food=$td_next_food
    fi
    td_head=$expected td_digest=$fields[8]
    (( expected += 1 ))
  done
  (( td_head >= 0 )) || { _td_fail 'genesis receipt missing'; return 1; }
  return 0
}

_td_lock() {
  [[ -d $td_dir && ! -L $td_dir ]] || { _td_fail 'world directory missing or symlinked'; return 1; }
  mkdir -- "$td_dir/.writer-lock" 2>/dev/null || {
    _td_fail 'writer lock present; inspect before recovery'; return 1
  }
  td_lock_token="$$-$RANDOM-$RANDOM"
  print -r -- "$$|$td_lock_token" > "$td_dir/.writer-lock/owner" || {
    rmdir -- "$td_dir/.writer-lock" 2>/dev/null
    _td_fail 'could not record lock owner'; return 1
  }
}

_td_unlock() {
  local owner
  [[ -f $td_dir/.writer-lock/owner && ! -L $td_dir/.writer-lock/owner ]] || return 1
  owner=$(<"$td_dir/.writer-lock/owner")
  [[ $owner == "$$|$td_lock_token" ]] || return 1
  rm -- "$td_dir/.writer-lock/owner" && rmdir -- "$td_dir/.writer-lock"
}

_td_locked() {
  _td_lock || return 1
  { "$@" } always { _td_unlock }
}

_td_append() {
  local action=$1 name body REPLY pending
  local -i seq=$(( td_head + 1 ))
  (( seq <= 999999 )) || { _td_fail 'receipt capacity reached'; return 1; }
  builtin printf -v name '%06d.receipt' $seq
  [[ ! -e $td_dir/events/$name && ! -L $td_dir/events/$name ]] || {
    _td_fail 'receipt already exists'; return 1
  }
  body="TENDORA/1|$seq|$td_digest|$action|$td_next_water|$td_next_beds|$td_next_food"
  _td_checksum "$body"
  pending="$td_dir/events/.pending-$td_lock_token"
  print -r -- "$body|$REPLY" > "$pending" || return 1
  mv -- "$pending" "$td_dir/events/$name" || return 1
  print -r -- "committed $name: $action; water=$td_next_water beds=$td_next_beds food=$td_next_food; checksum=$REPLY"
}

_td_init_locked() {
  local -a entries
  entries=( "$td_dir"/*(DN) )
  (( ${#entries} == 1 )) && [[ ${entries[1]:t} == .writer-lock ]] || {
    _td_fail 'init refuses nonempty material'; return 1
  }
  mkdir -- "$td_dir/events" "$td_dir/proposals" || return 1
  td_head=-1 td_digest=0 td_next_water=4 td_next_beds=0 td_next_food=0
  _td_append awaken
}

_td_propose_loaded() {
  local action=$1 id body pending
  case $action in collect|plant|harvest) ;; *) _td_fail "unknown action: $action"; return 1;; esac
  builtin printf -v id '%06d-%s' $td_head "$action"
  body="TENDORA-PROPOSAL/1|$td_head|$td_digest|$action"
  if [[ -e $td_dir/proposals/$id.proposal || -L $td_dir/proposals/$id.proposal ]]; then
    [[ -f $td_dir/proposals/$id.proposal && ! -L $td_dir/proposals/$id.proposal && $(<"$td_dir/proposals/$id.proposal") == $body ]] || {
      _td_fail 'existing proposal differs'; return 1
    }
  else
    pending="$td_dir/proposals/.pending-$td_lock_token"
    print -r -- "$body" > "$pending" && mv -- "$pending" "$td_dir/proposals/$id.proposal" || return 1
  fi
  td_proposal_id=$id
  print -r -- "$id"
}

_td_propose() { _td_load && _td_propose_loaded "$1"; }

_td_read_proposal() {
  local id=$1 line expected
  local -a fields
  [[ $id == [0-9][0-9][0-9][0-9][0-9][0-9]-(collect|plant|harvest) ]] || {
    _td_fail 'invalid proposal ID'; return 1
  }
  [[ -f $td_dir/proposals/$id.proposal && ! -L $td_dir/proposals/$id.proposal ]] || {
    _td_fail 'proposal missing or symlinked'; return 1
  }
  line=$(<"$td_dir/proposals/$id.proposal")
  fields=( "${(@s:|:)line}" )
  (( ${#fields} == 4 )) && [[ $fields[1] == TENDORA-PROPOSAL/1 && $line != *$'\n'* ]] || {
    _td_fail 'malformed proposal'; return 1
  }
  [[ $fields[2] == $td_head && $fields[3] == $td_digest ]] || {
    _td_fail 'stale proposal; propose again from the current head'; return 1
  }
  builtin printf -v expected '%06d-%s' $td_head "$fields[4]"
  [[ $id == $expected ]] || { _td_fail 'proposal ID disagrees with contents'; return 1; }
  td_action=$fields[4]
  _td_transition "$td_action"
}

_td_commit() {
  _td_load && _td_read_proposal "$1" && _td_append "$td_action"
}

_td_policy() {
  if (( td_food >= 12 )); then REPLY=pause
  elif (( td_beds > 0 && td_water >= 3 )); then REPLY=harvest
  elif (( td_beds < 3 && td_water >= 4 )); then REPLY=plant
  else REPLY=collect
  fi
}

_td_step() {
  local REPLY
  _td_load || return 1
  _td_policy
  if [[ $REPLY == pause ]]; then print -r -- 'paused: goal reached'; return 0; fi
  _td_propose_loaded "$REPLY" || return 1
  _td_read_proposal "$td_proposal_id" && _td_append "$td_action"
}

_td_recover() {
  local requested=$1 owner token pid
  local -a fields entries
  [[ -d $td_dir/.writer-lock && ! -L $td_dir/.writer-lock ]] || { _td_fail 'no recoverable lock'; return 1; }
  entries=( "$td_dir"/.writer-lock/*(DN) )
  if (( ${#entries} == 0 )); then
    [[ $requested == owner-missing ]] || { _td_fail 'owner absent; explicit owner-missing token required'; return 1; }
    rmdir -- "$td_dir/.writer-lock" || return 1
  else
    (( ${#entries} == 1 )) && [[ ${entries[1]:t} == owner && -f ${entries[1]} && ! -L ${entries[1]} ]] || {
      _td_fail 'malformed lock; preserve it for manual investigation'; return 1
    }
    owner=$(<"$td_dir/.writer-lock/owner")
    fields=( "${(@s:|:)owner}" )
    (( ${#fields} == 2 )) && [[ $fields[1] == [1-9][0-9]# && ${#fields[1]} -le 10 && $fields[2] == [0-9]##-[0-9]##-[0-9]## ]] || {
      _td_fail 'malformed owner; preserve it for manual investigation'; return 1
    }
    pid=$fields[1] token=$fields[2]
    [[ $requested == $token ]] || { _td_fail 'recovery token mismatch'; return 1; }
    if kill -0 "$pid" 2>/dev/null; then _td_fail 'owner process still exists; refusing recovery'; return 1; fi
    rm -- "$td_dir/.writer-lock/owner" && rmdir -- "$td_dir/.writer-lock" || return 1
  fi
  print -r -- 'writer lock recovered; committed receipts preserved'
}

_td_main() {
  emulate -L zsh
  setopt extendedglob
  local LC_ALL=C
  zmodload zsh/files || { _td_fail 'Zsh files module required'; return 1; }
  local td_program=${${(%):-%x}:A:h}
  local td_dir=${TENDORA_STATE_DIR:-$td_program/state}
  local td_lock_token td_proposal_id td_action REPLY
  local -i td_water td_beds td_food td_head td_digest td_pending
  local -i td_next_water td_next_beds td_next_food i
  local command=${1:-inspect}
  (( $# > 0 )) && shift
  [[ $td_dir == /* && $td_dir != / && ! -L $td_dir ]] || {
    _td_fail 'state directory must be an absolute non-root, non-symlink path'; return 1
  }
  case $command in
    init|inspect|verify|step|help) (( $# == 0 )) || { _td_fail 'unexpected arguments'; return 1; };;
    propose|rehearse|commit|run|recover) (( $# == 1 )) || { _td_fail "$command requires one argument"; return 1; };;
    *) _td_fail "unknown command: $command"; return 1;;
  esac
  case $command in
    help)
      print -r -- 'Tendora: init | inspect | verify | propose collect/plant/harvest | rehearse ID | commit ID | step | run N (1..20) | recover TOKEN'
      ;;
    init)
      [[ -d $td_dir ]] || mkdir -p -- "$td_dir" || return 1
      _td_locked _td_init_locked
      ;;
    inspect|verify)
      _td_load || return 1
      print -r -- "verified $(( td_head + 1 )) receipts; head=$td_head checksum=$td_digest"
      print -r -- "water=$td_water/12 (reserve=2) beds=$td_beds/3 food=$td_food/12"
      if [[ $command == inspect ]]; then
        _td_policy
        print -r -- "next=$REPLY; ignored incomplete event files=$td_pending"
        if [[ -d $td_dir/.writer-lock ]]; then
          if [[ -f $td_dir/.writer-lock/owner && ! -L $td_dir/.writer-lock/owner ]]; then
            print -r -- "writer lock: $(<"$td_dir/.writer-lock/owner")"
          else print -r -- 'writer lock: owner-missing or malformed'; fi
        fi
      fi
      ;;
    propose) _td_locked _td_propose "$1";;
    rehearse)
      _td_load && _td_read_proposal "$1" || return 1
      print -r -- "rehearsed $1: water=$td_next_water beds=$td_next_beds food=$td_next_food; no event committed"
      ;;
    commit) _td_locked _td_commit "$1";;
    step) _td_locked _td_step;;
    run)
      [[ $1 == [1-9] || $1 == 1[0-9] || $1 == 20 ]] || { _td_fail 'run requires an integer from 1 to 20'; return 1; }
      for (( i=0; i<$1; i++ )); do
        _td_locked _td_step || return 1
        (( td_food >= 12 || td_next_food >= 12 )) && break
      done
      return 0
      ;;
    recover) _td_recover "$1";;
  esac
}

_td_main "$@"
